package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct { // 01 DISC-REC, 15 bytes
	DrItem  string          // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct   int64           // PIC 9(2) @13 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsDiscount decimal.Decimal = decimal.Zero // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal = decimal.Zero // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal = decimal.Zero // PIC 9(8)V99 len=10 = 0
var WsCount int64 = 0 // PIC 9(3) len=3 = 0
var WsPriceEd string // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string // PIC ZZ,ZZ9.99 len=9
var WsNetEd string // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var discData DiscRec

var discLines []string
var discIdx int
var discFile *os.File

func inputDone() bool {
	return WsEofFlag == "Y"
}

func storeScaled(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	t := v.Truncate(scale)
	mod := decimal.New(1, int32(intDigits)+scale)
	scaled := t.Shift(scale).Truncate(0)
	// keep low-order digits
	m := scaled.Mod(mod)
	// shopspring Mod keeps sign of dividend; for negative values this gives negative remainder which matches low-order truncation
	return m.Shift(-scale)
}

func formatEdited(v decimal.Decimal, pic string) string {
	// count integer digit slots and frac slots
	// pic like "ZZ,ZZ9.99"
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	intSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	fracSlots := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracSlots++
		}
	}
	// scale value to fracSlots, truncate toward zero
	sc := int32(fracSlots)
	t := v.Truncate(sc)
	neg := t.IsNegative()
	if neg {
		t = t.Neg()
	}
	scaled := t.Shift(sc).Truncate(0).IntPart()
	fracMod := int64(1)
	for i := 0; i < fracSlots; i++ {
		fracMod *= 10
	}
	var intPart, fracPart int64
	if fracSlots > 0 {
		intPart = scaled / fracMod
		fracPart = scaled % fracMod
	} else {
		intPart = scaled
		fracPart = 0
	}
	// keep low-order int digits
	modInt := int64(1)
	for i := 0; i < intSlots; i++ {
		modInt *= 10
	}
	intPart = intPart % modInt
	intStr := fmt.Sprintf("%0*d", intSlots, intPart)
	fracStr := ""
	if fracSlots > 0 {
		fracStr = fmt.Sprintf("%0*d", fracSlots, fracPart)
	}
	// map intStr digits onto intPic
	out := make([]byte, 0, len(pic)+2)
	digitIdx := 0
	suppressed := true
	// need digits array
	digits := []byte(intStr)
	// iterate over intPic chars
	for i := 0; i < len(intPic); i++ {
		ch := intPic[i]
		switch ch {
		case 'Z':
			d := digits[digitIdx]
			digitIdx++
			if suppressed && d == '0' {
				out = append(out, ' ')
			} else {
				out = append(out, d)
				suppressed = false
			}
		case '9':
			d := digits[digitIdx]
			digitIdx++
			out = append(out, d)
			suppressed = false
		case ',':
			if suppressed {
				out = append(out, ' ')
			} else {
				out = append(out, ',')
			}
		case '.':
			out = append(out, '.')
		default:
			out = append(out, ch)
		}
	}
	if dotIdx >= 0 {
		out = append(out, '.')
		// fracPic: all '9's, just output fracStr
		// handle any literal in fracPic (not needed)
		for i := 0; i < len(fracPic); i++ {
			ch := fracPic[i]
			if ch == 'Z' || ch == '9' {
				// take next frac digit
				// fracStr index
				// find position
				// simpler: sequential
				idx := 0
				// count how many digit slots already consumed
				consumed := 0
				for j := 0; j < i; j++ {
					if fracPic[j] == 'Z' || fracPic[j] == '9' {
						consumed++
					}
				}
				idx = consumed
				if idx < len(fracStr) {
					out = append(out, fracStr[idx])
				} else {
					out = append(out, '0')
				}
			} else {
				out = append(out, ch)
			}
		}
	}
	s := string(out)
	if neg {
		// unsigned fields never negative; ignore sign handling
	}
	return s
}

func parsePrice(s string) decimal.Decimal {
	// s length 7, digits only; spaces treated as zero
	if len(s) < 7 {
		s = s + strings.Repeat(" ", 7-len(s))
	}
	var n int64
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return decimal.New(n, -2)
}

func parsePct(s string) int64 {
	if len(s) < 2 {
		s = s + strings.Repeat(" ", 2-len(s))
	}
	var n int64
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		n = n*10 + d
	}
	// keep low-order 2 digits (already)
	n = n % 100
	return n
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func MainPara() {
	// OPEN INPUT DISC-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file does not exist, treat as empty
		if os.IsNotExist(err) {
			discLines = []string{}
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		discFile = f
		scanner := bufio.NewScanner(f)
		// allow long lines
		scanner.Buffer(make([]byte, 1024*1024), 1024*1024)
		for scanner.Scan() {
			line := scanner.Text()
			discLines = append(discLines, line)
		}
		f.Close()
	}
	discIdx = 0
	ReadPara()
	for !inputDone() {
		ProcessPara()
	}
	// CLOSE DISC-FILE (already closed)
	SummaryPara()
}

func ReadPara() {
	if discIdx >= len(discLines) {
		WsEofFlag = "Y"
		return
	}
	line := discLines[discIdx]
	discIdx++
	// pad with spaces to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	item := line[0:6]
	priceStr := line[6:13]
	pctStr := line[13:15]
	discData.DrItem = padRight(item, 6)
	discData.DrPrice = parsePrice(priceStr)
	discData.DrPct = parsePct(pctStr)
}

func ProcessPara() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	prod := discData.DrPrice.Mul(decimal.NewFromInt(discData.DrPct))
	q := prod.Shift(-2)
	r := q.Round(2)
	WsDiscount = storeScaled(r, 5, 2)
	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	diff := discData.DrPrice.Sub(WsDiscount)
	WsNet = storeScaled(diff, 5, 2)
	// ADD WS-NET TO WS-TOTAL-NET
	WsTotalNet = storeScaled(WsTotalNet.Add(WsNet), 8, 2)
	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 1000
	// MOVE ...
	WsPriceEd = formatEdited(discData.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")
	// DISPLAY
	pctStr := fmt.Sprintf("%02d", discData.DrPct)
	line := discData.DrItem + " " + WsPriceEd + " " + pctStr + "% " + WsDiscEd + " " + WsNetEd
	fmt.Println(line)
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Println("ITEMS: " + countStr + " NET TOTAL: " + WsTotalEd)
}

func main() {
	MainPara()
}
